async function handleEditClick(bundleId: BundleId): Promise<void> {
  // Fetch full bundle detail from list data (we only have summary fields here).
  // Re-fetch via the list to populate form. For edit we'll pre-populate
  // what we have and ask the merchant to verify.
  const summary = state.bundles.find((b) => b.id === bundleId);
  if (!summary) return;
  state.view = "edit";
  state.editingBundle = bundleId;
  state.formState = {
    name: summary.name,
    bundle_type: summary.bundle_type,
    enabled: summary.enabled,
    required_item_count: null,
    discount_type: "percentage",
    items: [],
    discount_tiers: [{ min_item_count: 2, discount_ratio: "0.10" }],
    shopify_discount_external_id: null,
    discount_code_string: null,
  };
  bridge.saveBar.show("bundle-form");
  render();
}

